   190  static void
   191  jpeg_pipeline_dest(j_compress_ptr cinfo,
   192                     unsigned char* outbuffer, size_t size,
   193                     Pipeline* next)
   194  {
   195      cinfo->dest = static_cast<struct jpeg_destination_mgr *>(
   196          (*cinfo->mem->alloc_small)(reinterpret_cast<j_common_ptr>(cinfo),
   197                                     JPOOL_PERMANENT,
   198                                     sizeof(dct_pipeline_dest)));
   199      dct_pipeline_dest* dest =
   200          reinterpret_cast<dct_pipeline_dest*>(cinfo->dest);
   201      dest->pub.init_destination = init_pipeline_destination;
   202      dest->pub.empty_output_buffer = empty_pipeline_output_buffer;
   203      dest->pub.term_destination = term_pipeline_destination;
   204      dest->pub.next_output_byte = dest->buffer = outbuffer;
   205      dest->pub.free_in_buffer = dest->size = size;
   206      dest->next = next;
   207  }
